```
/* Parse command line arguments */
static int parse_args(int argc, char **argv) {
    int i;
    int show_help = 0;
    int show_version = 0;

    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0 || 
            strcmp(argv[i], "--help") == 0) {
            show_help = 1;
        } else if (strcmp(argv[i], "-V") == 0 || strcmp(argv[i], "--version") == 0) {
            show_version = 1;
        }
        // ... other option parsing ...
    }

    if (show_help) {
        print_usage();
        return 1;  /* FIXED: was return 0, causing run_matrix() to be called */
    }
    if (show_version) {
        print_version();
        return 1;  /* FIXED: was return 0, causing run_matrix() to be called */
    }

    return 0;
}

int main(int argc, char **argv) {
    int result;

    result = parse_args(argc, argv);
    if (result == 0) {
        srand(time(NULL));
        run_matrix();
    }

    return result;
}
