/* Get random character */
static char get_random_char(void) {
    if (lambda_mode) {
        return 'λ';
    }
    if (chars_change) {
        return matrix_chars[rand() % (strlen(matrix_chars) + 1)];
    }
    return ' ';
}

/* Get random katakana character */
static char get_random_katakana(void) {
    return katakana_chars[rand() % strlen(katakana_chars)];
}

/* Get random character for matrix */
static char get_matrix_char(void) {
    if (only_shadows) {
        return ' ';
    }
    if (rand() % 2) {
        return get_random_char();
    }
    return ' ';
}

