/*
 * CMatrix - A Matrix-like terminal screensaver
 * Based on the screensaver from The Matrix website
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <time.h>
#include <ctype.h>
#include <math.h>
#include <sys/ioctl.h>
#include <wchar.h>

#define VERSION "2.0"
#define DEFAULT_DELAY 4
#define MAX_COLS 200
#define MAX_ROWS 100

/* Color definitions */
typedef enum {
    COLOR_GREEN = 0,
    COLOR_RED,
    COLOR_BLUE,
    COLOR_WHITE,
    COLOR_YELLOW,
    COLOR_CYAN,
    COLOR_MAGENTA,
    COLOR_BLACK
} Color;

/* Program options */
static int async_scroll = 0;
static int bold_chars = 0;
static int all_bold = 0;
static int no_bold = 0;
static int force_term = 0;
static int linux_mode = 0;
static int old_scroll = 0;
static int only_shadows = 0;
static int lock_mode = 0;
static int rainbow_mode = 0;
static int lambda_mode = 0;
static int chars_change = 0;
static int x_mode = 0;
static int screensaver_mode = 0;
static int tty_set = 0;
static int message_mode = 0;
static int update_delay = DEFAULT_DELAY;
static Color matrix_color = COLOR_GREEN;
static char *center_message = NULL;

/* Matrix data */
static char matrix[MAX_ROWS][MAX_COLS];
static int cols, rows;
static char *matrix_chars = "01";
static char *katakana_chars = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッン";

/* Get random character */
static char get_random_char(void) {
    if (lambda_mode) {
        return 'λ';
    }
    if (chars_change) {
        return matrix_chars[rand() % (strlen(matrix_chars) + 1)];
    }
    return ' ';
}

/* Get random katakana character */
static char get_random_katakana(void) {
    return katakana_chars[rand() % strlen(katakana_chars)];
}

/* Get random character for matrix */
static char get_matrix_char(void) {
    if (only_shadows) {
        return ' ';
    }
    if (rand() % 2) {
        return get_random_char();
    }
    return ' ';
}

/* Set terminal attributes */
static void set_term_attrs(int fg, int bg) {
    printf("\033[%d;%dm", fg, bg);
    fflush(stdout);
}

/* Reset terminal attributes */
static void reset_term_attrs(void) {
    printf("\033[0m");
    fflush(stdout);
}

/* Print usage */
static void print_usage(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

/* Print version */
static void print_version(void) {
    printf(" CMatrix version %s (compiled 22:13:51, Jun 11 2026)\n", VERSION);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

/* Parse color string */
static Color parse_color(const char *color) {
    if (strcmp(color, "green") == 0) return COLOR_GREEN;
    if (strcmp(color, "red") == 0) return COLOR_RED;
    if (strcmp(color, "blue") == 0) return COLOR_BLUE;
    if (strcmp(color, "white") == 0) return COLOR_WHITE;
    if (strcmp(color, "yellow") == 0) return COLOR_YELLOW;
    if (strcmp(color, "cyan") == 0) return COLOR_CYAN;
    if (strcmp(color, "magenta") == 0) return COLOR_MAGENTA;
    if (strcmp(color, "black") == 0) return COLOR_BLACK;
    return COLOR_GREEN;
}

/* Get color attribute */
static int get_color_attr(Color c) {
    switch (c) {
        case COLOR_GREEN: return 32;
        case COLOR_RED: return 31;
        case COLOR_BLUE: return 34;
        case COLOR_WHITE: return 37;
        case COLOR_YELLOW: return 33;
        case COLOR_CYAN: return 36;
        case COLOR_MAGENTA: return 35;
        case COLOR_BLACK: return 30;
        default: return 32;
    }
}

/* Get background attribute */
static int get_bg_attr(Color c) {
    switch (c) {
        case COLOR_GREEN: return 42;
        case COLOR_RED: return 41;
        case COLOR_BLUE: return 44;
        case COLOR_WHITE: return 47;
        case COLOR_YELLOW: return 43;
        case COLOR_CYAN: return 46;
        case COLOR_MAGENTA: return 45;
        case COLOR_BLACK: return 40;
        default: return 42;
    }
}

/* Get rainbow color */
static int get_rainbow_color(int row) {
    int colors[] = {31, 32, 33, 34, 35, 36, 37};
    return colors[row % 7];
}

/* Get rainbow background */
static int get_rainbow_bg(int row) {
    int colors[] = {41, 42, 43, 44, 45, 46, 47};
    return colors[row % 7];
}

/* Initialize terminal */
static void init_terminal(void) {
    struct termios oldt, newt;

    if (tcgetattr(STDIN_FILENO, &oldt) == -1) {
        return;
    }

    newt = oldt;
    newt.c_lflag &= ~(ECHO | ICANON);
    newt.c_cc[VMIN] = 0;
    newt.c_cc[VTIME] = 0;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &newt) == -1) {
        return;
    }

    if (force_term) {
        setenv("TERM", "linux", 1);
    }
}

/* Restore terminal */
static void restore_terminal(struct termios *oldt) {
    tcsetattr(STDIN_FILENO, TCSANOW, oldt);
}

/* Get terminal size */
static void get_term_size(int *cols, int *rows) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == -1) {
        *cols = 80;
        *rows = 24;
    } else {
        *cols = ws.ws_col;
        *rows = ws.ws_row;
    }
}

/* Initialize matrix */
static void init_matrix(void) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            matrix[i][j] = get_matrix_char();
        }
    }
}

/* Draw the matrix */
static void draw_matrix(void) {
    int fg, bg;

    if (rainbow_mode) {
        fg = get_rainbow_color(0);
        bg = get_rainbow_bg(0);
    } else {
        fg = get_color_attr(matrix_color);
        bg = get_bg_attr(matrix_color);
    }

    set_term_attrs(fg, bg);

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%c", matrix[i][j]);
        }
        printf("\n");
    }

    reset_term_attrs();
}

/* Draw center message */
static void draw_message(void) {
    if (center_message) {
        int mid_row = rows / 2;
        int mid_col = cols / 2;

        printf("\033[%d;%dH", mid_row + 1, mid_col + 1);
        printf("%s\n", center_message);
    }
}

/* Handle keystrokes */
static void handle_keystrokes(struct termios *oldt) {
    char c;
    fd_set readfds;
    struct timeval tv;

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(STDIN_FILENO, &readfds);

        tv.tv_sec = 0;
        tv.tv_usec = 100000;

        if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
            if (read(STDIN_FILENO, &c, 1) > 0) {
                if (c == 'q' || c == 'Q') {
                    break;
                } else if (c == 'a') {
                    async_scroll = !async_scroll;
                } else if (c == 'b') {
                    bold_chars = 1;
                    all_bold = 0;
                    no_bold = 0;
                } else if (c == 'B') {
                    all_bold = 1;
                    bold_chars = 0;
                    no_bold = 0;
                } else if (c == 'n') {
                    no_bold = 1;
                    bold_chars = 0;
                    all_bold = 0;
                } else if (isdigit(c)) {
                    update_delay = c - '0';
                } else if (c == '!') {
                    matrix_color = COLOR_RED;
                } else if (c == '@') {
                    matrix_color = COLOR_GREEN;
                } else if (c == '#') {
                    matrix_color = COLOR_YELLOW;
                } else if (c == '$') {
                    matrix_color = COLOR_BLUE;
                } else if (c == '%') {
                    matrix_color = COLOR_MAGENTA;
                } else if (c == '^') {
                    matrix_color = COLOR_CYAN;
                } else if (c == '&') {
                    matrix_color = COLOR_WHITE;
                } else if (c == ')') {
                    matrix_color = COLOR_BLACK;
                }
            }
        }
    }
}

/* Main loop */
static void run_matrix(void) {
    struct termios oldt;
    int old_stdout = dup(STDOUT_FILENO);
    int old_stderr = dup(STDERR_FILENO);

    init_terminal();
    get_term_size(&cols, &rows);
    init_matrix();

    /* Clear screen */
    printf("\033[2J\033[H");

    /* Draw initial message */
    if (center_message) {
        printf("\033[2J\033[H");
        printf("\033[%d;%dH", rows / 2 + 1, cols / 2 + 1);
        printf("%s\n", center_message);
    }

    /* Main loop */
    while (1) {
        /* Update matrix */
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (rand() % 100 < 5) {
                    matrix[i][j] = get_matrix_char();
                }
            }
        }

        /* Draw */
        draw_matrix();
        draw_message();

        /* Handle keystrokes */
        if (!screensaver_mode) {
            handle_keystrokes(&oldt);
        }

        /* Sleep based on delay */
        usleep(update_delay * 100000);
    }

    restore_terminal(&oldt);
    dup2(old_stdout, STDOUT_FILENO);
    dup2(old_stderr, STDERR_FILENO);
    close(old_stdout);
    close(old_stderr);
}

/* Parse command line arguments */
static int parse_args(int argc, char **argv) {
    int i;
    int show_help = 0;
    int show_version = 0;

    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0 || 
            strcmp(argv[i], "--help") == 0) {
            show_help = 1;
        } else if (strcmp(argv[i], "-V") == 0 || strcmp(argv[i], "--version") == 0) {
            show_version = 1;
        } else if (strcmp(argv[i], "-a") == 0) {
            async_scroll = 1;
        } else if (strcmp(argv[i], "-b") == 0) {
            bold_chars = 1;
        } else if (strcmp(argv[i], "-B") == 0) {
