                tty_set = 1;
            }
        } else if (argv[i][0] == '-') {
            fprintf(stderr, "Unknown option: %s\n", argv[i]);
            print_usage();
            return 1;
        }
    }

    if (show_help) {
        print_usage();
        return 0;
    }
    if (show_version) {
        print_version();
        return 0;
    }

    return 0;
}

