static Color parse_color(const char *color) {
    if (strcmp(color, "green") == 0) return COLOR_GREEN;
    if (strcmp(color, "red") == 0) return COLOR_RED;
    if (strcmp(color, "blue") == 0) return COLOR_BLUE;
    if (strcmp(color, "white") == 0) return COLOR_WHITE;
    if (strcmp(color, "yellow") == 0) return COLOR_YELLOW;
    if (strcmp(color, "cyan") == 0) return COLOR_CYAN;
    if (strcmp(color, "magenta") == 0) return COLOR_MAGENTA;
    if (strcmp(color, "black") == 0) return COLOR_BLACK;
    return COLOR_GREEN;
}

/* Get color attribute */
static int get_color_attr(Color c) {
    switch (c) {
        case COLOR_GREEN: return 32;
        case COLOR_RED: return 31;
        case COLOR_BLUE: return 34;
        case COLOR_WHITE: return 37;
        case COLOR_YELLOW: return 33;
        case COLOR_CYAN: return 36;
        case COLOR_MAGENTA: return 35;
        case COLOR_BLACK: return 30;
        default: return 32;
    }
}

/* Get background attribute */
static int get_bg_attr(Color c) {
    switch (c) {
        case COLOR_GREEN: return 42;
        case COLOR_RED: return 41;
        case COLOR_BLUE: return 44;
        case COLOR_WHITE: return 47;
        case COLOR_YELLOW: return 43;
        case COLOR_CYAN: return 46;
        case COLOR_MAGENTA: return 45;
        case COLOR_BLACK: return 40;
        default: return 42;
    }
}

