/* Handle keystrokes */
static void handle_keystrokes(struct termios *oldt) {
    char c;
    fd_set readfds;
    struct timeval tv;

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(STDIN_FILENO, &readfds);

        tv.tv_sec = 0;
        tv.tv_usec = 100000;

        if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
            if (read(STDIN_FILENO, &c, 1) > 0) {
                if (c == 'q' || c == 'Q') {
                    break;
                } else if (c == 'a') {
                    async_scroll = !async_scroll;
                } else if (c == 'b') {
                    bold_chars = 1;
                    all_bold = 0;
                    no_bold = 0;
                } else if (c == 'B') {
                    all_bold = 1;
                    bold_chars = 0;
                    no_bold = 0;
                } else if (c == 'n') {
                    no_bold = 1;
                    bold_chars = 0;
                    all_bold = 0;
                } else if (isdigit(c)) {
                    update_delay = c - '0';
                } else if (c == '!') {
                    matrix_color = COLOR_RED;
                } else if (c == '@') {
                    matrix_color = COLOR_GREEN;
                } else if (c == '#') {
