#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <time.h>
#include <ctype.h>
#include <math.h>
#include <sys/ioctl.h>
#include <wchar.h>

#define VERSION "2.0"
#define DEFAULT_DELAY 4
#define MAX_COLS 200
#define MAX_ROWS 100

/* Color definitions */
typedef enum {
    COLOR_GREEN = 0,
    COLOR_RED,
    COLOR_BLUE,
    COLOR_WHITE,
    COLOR_YELLOW,
    COLOR_CYAN,
    COLOR_MAGENTA,
    COLOR_BLACK
} Color;

/* Program options */
