+    COLOR_RED,
+    COLOR_BLUE,
+    COLOR_WHITE,
+    COLOR_YELLOW,
+    COLOR_CYAN,
+    COLOR_MAGENTA,
+    COLOR_BLACK
+} Color;
+
+/* Program options */
