static void restore_terminal(struct termios *oldt) {
    tcsetattr(STDIN_FILENO, TCSANOW, oldt);
}

/* Get terminal size */
static void get_term_size(int *cols, int *rows) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == -1) {
        *cols = 80;
        *rows = 24;
    } else {
        *cols = ws.ws_col;
        *rows = ws.ws_row;
    }
}

/* Initialize matrix */
static void init_matrix(void) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            matrix[i][j] = get_matrix_char();
        }
    }
}

/* Draw the matrix */
static void draw_matrix(void) {
    int fg, bg;

    if (rainbow_mode) {
        fg = get_rainbow_color(0);
        bg = get_rainbow_bg(0);
    } else {
        fg = get_color_attr(matrix_color);
        bg = get_bg_attr(matrix_color);
    }

    set_term_attrs(fg, bg);

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%c", matrix[i][j]);
        }
        printf("\n");
    }

    reset_term_attrs();
}

/* Draw center message */
static void draw_message(void) {
    if (center_message) {
        int mid_row = rows / 2;
        int mid_col = cols / 2;

        printf("\033[%d;%dH", mid_row + 1, mid_col + 1);
        printf("%s\n", center_message);
    }
}

/* Handle keystrokes */
static void handle_keystrokes(struct termios *oldt) {
    char c;
    fd_set readfds;
    struct timeval tv;

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(STDIN_FILENO, &readfds);

        tv.tv_sec = 0;
        tv.tv_usec = 100000;

        if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
            if (read(STDIN_FILENO, &c, 1) > 0) {
                if (c == 'q' || c == 'Q') {
                    break;
                } else if (c == 'a') {
                    async_scroll = !async_scroll;
                } else if (c == 'b') {
                    bold_chars = 1;
                    all_bold = 0;
                    no_bold = 0;
                } else if (c == 'B') {
                    all_bold = 1;
                    bold_chars = 0;
                    no_bold = 0;
                } else if (c == 'n') {
                    no_bold = 1;
                    bold_chars = 0;
                    all_bold = 0;
                } else if (isdigit(c)) {
                    update_delay = c - '0';
                } else if (c == '!') {
                    matrix_color = COLOR_RED;
                } else if (c == '@') {
                    matrix_color = COLOR_GREEN;
                } else if (c == '#') {
                    matrix_color = COLOR_YELLOW;
                } else if (c == '$') {
                    matrix_color = COLOR_BLUE;
                } else if (c == '%') {
                    matrix_color = COLOR_MAGENTA;
                } else if (c == '^') {
                    matrix_color = COLOR_CYAN;
                } else if (c == '&') {
                    matrix_color = COLOR_WHITE;
                } else if (c == ')') {
                    matrix_color = COLOR_BLACK;
                }
            }
        }
    }
}

/* Main loop */
static void run_matrix(void) {
    struct termios oldt;
    int old_stdout = dup(STDOUT_FILENO);
    int old_stderr = dup(STDERR_FILENO);

    init_terminal();
    get_term_size(&cols, &rows);
    init_matrix();

    /* Clear screen */
    printf("\033[2J\033[H");

    /* Draw initial message */
    if (center_message) {
        printf("\033[2J\033[H");
        printf("\033[%d;%dH", rows / 2 + 1, cols / 2 + 1);
        printf("%s\n", center_message);
    }

    /* Main loop */
    while (1) {
        /* Update matrix */
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (rand() % 100 < 5) {
                    matrix[i][j] = get_matrix_char();
                }
            }
        }

        /* Draw */
        draw_matrix();
        draw_message();

        /* Handle keystrokes */
        if (!screensaver_mode) {
            handle_keystrokes(&oldt);
        }

        /* Sleep based on delay */
        usleep(update_delay * 100000);
    }

    restore_terminal(&oldt);
    dup2(old_stdout, STDOUT_FILENO);
    dup2(old_stderr, STDERR_FILENO);
    close(old_stdout);
    close(old_stderr);
}

/* Parse command line arguments */
static int parse_args(int argc, char **argv) {
    int i;
    int show_help = 0;
    int show_version = 0;

    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0 || 
            strcmp(argv[i], "--help") == 0) {
            show_help = 1;
        } else if (strcmp(argv[i], "-V") == 0 || strcmp(argv[i], "--version") == 0) {
            show_version = 1;
        } else if (strcmp(argv[i], "-a") == 0) {
            async_scroll = 1;
        } else if (strcmp(argv[i], "-b") == 0) {
            bold_chars = 1;
        } else if (strcmp(argv[i], "-B") == 0) {
            all_bold = 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            only_shadows = 1;
            matrix_chars = katakana_chars;
        } else if (strcmp(argv[i], "-f") == 0) {
            force_term = 1;
        } else if (strcmp(argv[i], "-l") == 0) {
            linux_mode = 1;
        } else if (strcmp(argv[i], "-L") == 0) {
            lock_mode = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            old_scroll = 1;
        } else if (strcmp(argv[i], "-n") == 0) {
            no_bold = 1;
        } else if (strcmp(argv[i], "-s") == 0) {
            screensaver_mode = 1;
        } else if (strcmp(argv[i], "-x") == 0) {
            x_mode = 1;
        } else if (strcmp(argv[i], "-r") == 0) {
            rainbow_mode = 1;
        } else if (strcmp(argv[i], "-m") == 0) {
            lambda_mode = 1;
        } else if (strcmp(argv[i], "-k") == 0) {
            chars_change = 1;
        } else if (strcmp(argv[i], "-u") == 0) {
            if (i + 1 < argc) {
                update_delay = atoi(argv[++i]);
                if (update_delay < 0 || update_delay > 10) {
                    fprintf(stderr, "Error: update delay must be 0-10\n");
                    return 1;
                }
            }
        } else if (strcmp(argv[i], "-C") == 0) {
            if (i + 1 < argc) {
                matrix_color = parse_color(argv[++i]);
            }
        } else if (strcmp(argv[i], "-M") == 0) {
            if (i + 1 < argc) {
                center_message = argv[++i];
                message_mode = 1;
            }
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 < argc) {
                setenv("TERM", argv[++i], 1);
                tty_set = 1;
            }
        } else if (argv[i][0] == '-') {
            fprintf(stderr, "Unknown option: %s\n", argv[i]);
            print_usage();
            return 1;
        }
    }

    if (show_help) {
        print_usage();
        return 1;
    }
    if (show_version) {
        print_version();
        return 1;
    }

    return 0;
}

int main(int argc, char **argv) {
    int result;

    result = parse_args(argc, argv);
    if (result == 0) {
        srand(time(NULL));
        run_matrix();
    }

    return result;
}
ENDPATCH

