+                if (c == 'q' || c == 'Q') {
+                    break;
+                } else if (c == 'a') {
+                    async_scroll = !async_scroll;
+                } else if (c == 'b') {
+                    bold_chars = 1;
+                    all_bold = 0;
+                    no_bold = 0;
+                } else if (c == 'B') {
+                    all_bold = 1;
+                    bold_chars = 0;
+                    no_bold = 0;
