}

static int get_color_index(const char *color) {
    if (strcmp(color, "green") == 0) return 1;
    if (strcmp(color, "red") == 0) return 2;
    if (strcmp(color, "blue") == 0) return 3;
    if (strcmp(color, "white") == 0) return 4;
    if (strcmp(color, "yellow") == 0) return 5;
    if (strcmp(color, "cyan") == 0) return 6;
    if (strcmp(color, "magenta") == 0) return 7;
    if (strcmp(color, "black") == 0) return 8;
    return 1;
