    .lock = 0,
    .rainbow = 0,
    .every_char = 0,
    .no_bold = 0,
    .screensaver = 0,
    .lambda_mode = 0,
    .x_mode = 0,
    .tty = 0,
    .update_delay = DEFAULT_DELAY,
    .color = NULL,
    .message = NULL,
    .use_japanese = 0
};

