{"command": "cat >> cmatrix.c << 'ENDOFFILE'

static void draw_matrix(void) {
    int i, j, x, y, col, row;
    int height, width;
    char *chars = "01";
    int char_count = 2;

    getmaxyx(stdscr, height, width);

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            if (opts.use_japanese) {
                mvaddch(i, j, '0');
            } else {
                mvaddch(i, j, chars[j % char_count]);
            }
        }
    }
    refresh();
}

static void draw_message(void) {
    int height, width;
    getmaxyx(stdscr, height, width);

    if (opts.message) {
        int msg_len = strlen(opts.message);
        int start = (width - msg_len) / 2;
        int y = height / 2;

        for (int i = 0; i < msg_len; i++) {
            mvaddch(y, start + i, opts.message[i]);
        }
        refresh();
    }
}

static void handle_key(int key) {
    if (opts.screensaver) {
        endwin();
        exit(0);
    }

    switch (key) {
        case 'a':
            opts.async = !opts.async;
            break;
        case 'b':
            opts.bold = !opts.bold;
            break;
        case 'B':
            opts.all_bold = 1;
            break;
        case 'n':
            opts.no_bold = 1;
            break;
        case 'q':
            endwin();
            exit(0);
        case 27:
            endwin();
            exit(0);
    }
}
ENDOFFILE"}

